// Two bars at 90 BPM. Each step is a sixteenth note: k = kick, s = snare, h = hi-hat.
const rate = 44100, bpm = 90;
const pattern = ["kh", "h", "h", "h", "sh", "h", "kh", "h", "h", "kh", "h", "h", "sh", "h", "h", "h"];
const step = 60 / bpm / 4;
const bars = 2;
const samples = new Float32Array(Math.round(rate * step * pattern.length * bars));
let seed = 7;
const noise = () => { seed = (seed * 1664525 + 1013904223) % 4294967296; return seed / 2147483648 - 1; };
for (let n = 0; n < pattern.length * bars; n++) {
  const hits = pattern[n % pattern.length];
  const start = Math.round(n * step * rate);
  for (let i = 0; i < rate * 0.5 && start + i < samples.length; i++) {
    const t = i / rate;
    let s = 0;
    if (hits.includes("k")) s += Math.sin(2 * Math.PI * (50 * t + 60 * (1 - Math.exp(-30 * t)) / 30)) * Math.exp(-8 * t);
    if (hits.includes("s")) s += 0.5 * noise() * Math.exp(-18 * t) + 0.3 * Math.sin(2 * Math.PI * 190 * t) * Math.exp(-20 * t);
    if (hits.includes("h") && t < 0.05) s += 0.15 * noise() * Math.exp(-90 * t);
    samples[start + i] += 0.6 * s;
  }
}

// 16-bit PCM WAV bytes from interleaved samples in [-1, 1].
function wav(samples, rate, channels) {
  const bytes = new Uint8Array(44 + samples.length * 2);
  const view = new DataView(bytes.buffer);
  const tag = (at, text) => { for (let i = 0; i < 4; i++) bytes[at + i] = text.charCodeAt(i); };
  tag(0, "RIFF"); view.setUint32(4, 36 + samples.length * 2, true); tag(8, "WAVE");
  tag(12, "fmt "); view.setUint32(16, 16, true); view.setUint16(20, 1, true);
  view.setUint16(22, channels, true); view.setUint32(24, rate, true);
  view.setUint32(28, rate * channels * 2, true); view.setUint16(32, channels * 2, true);
  view.setUint16(34, 16, true); tag(36, "data"); view.setUint32(40, samples.length * 2, true);
  samples.forEach((s, i) => view.setInt16(44 + i * 2, Math.round(Math.max(-1, Math.min(1, s)) * 32767), true));
  return bytes;
}

await output("audio", await media.toAudio(wav(samples, rate, 1), { mimeType: "audio/wav", filename: "drums.wav" }));
